export function validateGCDInput(i: GCDInput, lang: "en" | "es" = "en"): string | null {
  if (lang === "es") {
    if (i.numbers.length < 2) return "Ingresa al menos dos números enteros.";
    if (i.numbers.some((n) => n <= 0)) return "Ingresa solo números enteros positivos.";
    return null;
  }
  if (i.numbers.length < 2) return "Enter at least two whole numbers.";
  if (i.numbers.some((n) => n <= 0)) return "Enter only positive whole numbers.";
  return null;
}

